// Browser-side JPEG fixture: institutional heading, NIM/name/J.K., 16 slots, 21 rows.
module.exports=async function importAttendancePhoto(){
 const names=['ABUBAKAR ALIF THORIF','AFDAL','AHMADIN','ADRIANSAH','BULQIS','DANUL FARHAN','DELA FITA PUSPITA','DIA NOFITA','DINDA AMELIA','EKA','FITRI','FENIRIA','GUF RAN','HARUNI','HESTIN','ANGGUNG RADIATUL','JIN NANDA SUKMAYANTI','IRFAN SYAHPUTRA','JIHANSYAH PRATAMA','BUDI SANTOSO','ANA SAFITRI'];
 const canvas=document.createElement('canvas');canvas.width=1200;canvas.height=930;const g=canvas.getContext('2d');g.fillStyle='white';g.fillRect(0,0,1200,930);g.fillStyle='black';g.font='bold 17px Times New Roman';g.textAlign='center';g.fillText('SEKOLAH TINGGI KEGURUAN DAN ILMU PENDIDIKAN',600,100);g.fillText('YAYASAN PENDIDIKAN ISLAM DOMPU',600,125);g.fillText('PRODI PENDIDIKAN SEJARAH (S1)',600,150);g.font='14px Times New Roman';g.textAlign='left';g.fillText('Semester : V (Ganjil)',130,235);g.fillText('Tahun Akademik : 2026/2027',130,256);g.fillText('Prodi : Pendidikan Sejarah',130,277);g.fillText('Matakuliah :',760,235);g.fillText('Dosen Pengampu :',760,256);g.fillText('Kelas : A',760,277);
 const x=[130,165,340,575,610];for(let i=1;i<=16;i++)x.push(610+i*28);const top=305,first=365,height=23,bottom=first+21*height;g.lineWidth=1;g.strokeStyle='#444';for(const edge of x){g.beginPath();g.moveTo(edge,top);g.lineTo(edge,bottom);g.stroke();}for(const y of [top,first,...Array.from({length:21},(_,i)=>first+(i+1)*height)]){g.beginPath();g.moveTo(x[0],y);g.lineTo(x.at(-1),y);g.stroke();}g.beginPath();g.moveTo(610,335);g.lineTo(x.at(-1),335);g.stroke();g.font='bold 14px Times New Roman';g.fillText('NO',136,339);g.fillText('NIM',218,339);g.fillText('NAMA MAHASISWA',372,339);g.fillText('JK',581,339);g.fillText('Tanggal/Bulan',756,326);g.font='13px Times New Roman';for(let i=1;i<=16;i++)g.fillText(String(i),616+(i-1)*28,355);
 names.forEach((name,i)=>{const y=first+i*height+16;g.fillText(String(i+1),136,y);g.fillText('C722202401'+String(i+1).padStart(3,'0'),173,y);g.fillText(name,348,y);g.fillText(i%2?'P':'L',585,y);});
 const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.86)),file=new File([blob],'lembar-daftar-hadir.jpeg',{type:'image/jpeg'}),dt=new DataTransfer();dt.items.add(file);document.getElementById('fotoDaftarMahasiswa').files=dt.files;await muatPratinjauOcr();await bacaFotoDaftarMahasiswa();
 return {rows:Array.from(document.querySelectorAll('#ocrReviewRows tr'),row=>({nim:row.cells[0].querySelector('input')?.value,nama:row.cells[1].querySelector('input')?.value})),status:document.getElementById('ocrStatus').textContent,enabled:!document.getElementById('btnOcrFoto').disabled};
};
